var ctrl = GameObject.Find("VibratingPlatform (1)/Vibro Controller");
var audio = ctrl.GetComponent<AudioSource>();
var panel = ctrl.GetComponent<VibroControllerPanel>();
var listeners = Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include, FindObjectsSortMode.None);
var sb = new System.Text.StringBuilder();
sb.AppendLine($"AudioSource on '{ctrl.name}' at worldPos={ctrl.transform.position:F2}:");
sb.AppendLine($"  volume={audio.volume}, pitch={audio.pitch}, spatialBlend={audio.spatialBlend}, rolloffMode={audio.rolloffMode}, minDist={audio.minDistance}, maxDist={audio.maxDistance}, mixer={audio.outputAudioMixerGroup?.name ?? "NONE"}");
foreach (var l in listeners) {
  float d = Vector3.Distance(l.transform.position, ctrl.transform.position);
  sb.AppendLine($"AudioListener on '{l.name}' (active={l.gameObject.activeInHierarchy}, enabled={l.enabled}) at pos={l.transform.position:F2}, distToCtrl={d:F2}m");
}

string[] clipPaths = {
  "Assets/Audio/SFX_Vibro_Level1_Low.wav",
  "Assets/Audio/SFX_Vibro_Level2_Med.wav",
  "Assets/Audio/SFX_Vibro_Level3_High.wav",
  "Assets/Audio/SFX_Vibro_ButtonClick.wav"
};
foreach (var p in clipPaths) {
  var c = AssetDatabase.LoadAssetAtPath<AudioClip>(p);
  if (c == null) continue;
  float[] data = new float[c.samples * c.channels];
  c.GetData(data, 0);
  float peak = 0f; double sumSq = 0;
  for (int i = 0; i < data.Length; i++) { float a = Mathf.Abs(data[i]); if (a > peak) peak = a; sumSq += data[i] * data[i]; }
  float rms = Mathf.Sqrt((float)(sumSq / data.Length));
  float dbPeak = 20f * Mathf.Log10(Mathf.Max(peak, 0.00001f));
  float dbRms = 20f * Mathf.Log10(Mathf.Max(rms, 0.00001f));
  sb.AppendLine($"Clip '{c.name}': len={c.length:F2}s, freq={c.frequency}Hz, ch={c.channels}, peak={peak:F4} ({dbPeak:F1} dBFS), rms={rms:F4} ({dbRms:F1} dBFS)");
}
return sb.ToString();
